package codec

import (
	"bytes"
	"testing"
)

// Round-trip invariant: Decode(Encode(x)) must equal x.
func FuzzRoundTrip(f *testing.F) {
	f.Add([]byte("hello"))
	f.Fuzz(func(t *testing.T, in []byte) {
		out, err := Decode(Encode(in))
		if err != nil {
			t.Fatalf("decode: %v", err)
		}
		if !bytes.Equal(out, in) {
			t.Errorf("round-trip: got %q want %q", out, in)
		}
	})
}

package numx

import (
	"strconv"
	"testing"
)

// Our Atoi must agree with the standard library on every input.
func FuzzAtoi(f *testing.F) {
	f.Add("123")
	f.Add("99999999999999999999") // overflow
	f.Fuzz(func(t *testing.T, s string) {
		got, gotErr := Atoi(s)
		want, wantErr := strconv.Atoi(s)
		if (gotErr == nil) != (wantErr == nil) {
			t.Fatalf("Atoi(%q): error mismatch", s)
		}
		if gotErr == nil && got != want {
			t.Errorf("Atoi(%q)=%d want %d", s, got, want)
		}
	})
}

