package codec

import (
	"bytes"
	"testing"
)

// Encode/Decode are the functions under test (hex, base64, etc.).
func FuzzRoundTrip(f *testing.F) {
	f.Add([]byte(""))       // edge: empty input
	f.Add([]byte("hello")) // a normal value
	f.Add([]byte{0x00, 0xff})

	f.Fuzz(func(t *testing.T, in []byte) {
		encoded := Encode(in)
		decoded, err := Decode(encoded)
		if err != nil {
			t.Fatalf("Decode(Encode(%q)) errored: %v", in, err)
		}
		if !bytes.Equal(decoded, in) {
			t.Errorf("round-trip mismatch: got %q want %q", decoded, in)
		}
	})
}

