func FirstWord(s string) string {
	fields := strings.Fields(s)
	if len(fields) == 0 { // handle empty / whitespace-only input
		return ""
	}
	return fields[0]
}

func FuzzAtoi(f *testing.F) {
	f.Add("123")
	f.Add("-7")
	f.Add("")
	f.Add("+0")
	f.Add("99999999999999999999") // overflow case
	f.Fuzz(func(t *testing.T, s string) {
		got, gotErr := Atoi(s)
		want, wantErr := strconv.Atoi(s)
		// Both must agree on whether parsing succeeded.
		if (gotErr == nil) != (wantErr == nil) {
			t.Fatalf("Atoi(%q): error mismatch got=%v want=%v", s, gotErr, wantErr)
		}
		// On success, the values must match.
		if gotErr == nil && got != want {
			t.Errorf("Atoi(%q)=%d want %d", s, got, want)
		}
	})
}

func FuzzCodec(f *testing.F) {
	f.Add([]byte(""))                       // edge: empty input
	f.Add([]byte("key=value"))              // a plausible encoded value
	f.Add([]byte{0x00, 0xff, 0x3d, 0x0a})   // arbitrary/binary bytes

	f.Fuzz(func(t *testing.T, b []byte) {
		// Invariant 1: Decode must never panic on arbitrary bytes.
		// An error is acceptable; a panic is a bug (caught automatically).
		_, _ = Decode(b)

		// Invariant 2: round-trip. Build a deterministic map from the
		// fuzzed bytes, then require Decode(Encode(m)) == m.
		m := mapFromBytes(b)
		round, err := Decode(Encode(m))
		if err != nil {
			t.Fatalf("Decode(Encode(%v)) errored: %v", m, err)
		}
		if !reflect.DeepEqual(round, m) {
			t.Errorf("round-trip mismatch: got %v want %v", round, m)
		}
	})
}

// mapFromBytes derives a deterministic map so each fuzzed input yields
// a distinct, reproducible map to round-trip.
func mapFromBytes(b []byte) map[string]string {
	m := make(map[string]string)
	for i := 0; i+1 < len(b); i += 2 {
		k := fmt.Sprintf("k%d", b[i])
		m[k] = fmt.Sprintf("v%d", b[i+1])
	}
	return m
}
